<script setup lang="ts">
definePageMeta({ layout: "admin", middleware: "admin" });
useSeoMeta({ title: "Login methods | Portfolio admin", robots: "noindex, nofollow" });
interface Response { data: { providers: Array<{ id: string; key: string; type: string; label: string; enabled: boolean; activeConfigVersion: number | null; draftConfigVersion: number | null; latestConfig: null | { configVersion: number; clientId: string; secretConfigured: boolean; testedAt: string | null; updatedAt: string } }> } }
